"""Writes the per-video evidence records for the six research documents from the measured data (nothing typed by hand except channel/URL from a3list.txt + yt-dlp meta).
Outputs (into the repo, text only; no third-party frames are committed):
  docs/longform/research/phase3/VIDEO-RECORDS.md   one section per video: URL, duration, coverage, sampling, shares (sampled / segment-weighted), shot rhythm (two detectors), captions, audio, run table
  docs/longform/research/phase3/aggregate.json, segments.csv, labels/<id>.json, shots2 summary
Run-length table: consecutive sampled frames with the same label code are merged; each sample stands for 15 s centred on its timestamp. 'Frames' lists the contact-sheet tiles so the claim can be checked against the stored sheet (output/longform-research/a3/<id>/sheets/sNN.jpg, not committed)."""
import csv, json, os, shutil, statistics as st
HERE = os.path.dirname(os.path.abspath(__file__))
REPO = r"C:\Users\info\YOUTUBE\.worktrees\orch"; OUT = os.path.join(REPO, "docs", "longform", "research", "phase3"); os.makedirs(os.path.join(OUT, "labels"), exist_ok=True)
NAMES = {"V": "real footage (contemporary/B-roll/game capture)", "N": "news/broadcast footage", "I": "interview / public appearance", "H": "host on camera", "P": "photograph", "A": "archival film / film or TV clip", "R": "historical still / print / engraving", "S": "screen recording / software", "M": "map / satellite / geographic", "Q": "tactical diagram", "G": "data visualisation / chart", "D": "illustration / cartoon", "W": "whiteboard animation", "O": "original motion graphics / 3D", "F": "decorative / abstract", "T": "text-only card", "X": "document / screenshot / web page", "Z": "AI-generated imagery", "K": "stock footage", "B": "black / transition", "?": "unclassified"}
agg = {r["id"]: r for r in json.load(open(os.path.join(HERE, "aggregate.json")))}
rows = [l.split() for l in open(os.path.join(HERE, "a3list.txt")) if l.strip()]
def tc(s): s = int(round(s)); return f"{s//3600}:{s%3600//60:02d}:{s%60:02d}" if s >= 3600 else f"{s//60}:{s%60:02d}"
L = ["# Phase 3 per-video evidence records", "", "Generated by `output/longform-research/gen_records.py` from measured data. **Nothing here is invented.** Each record states how it was measured. Category shares are from labels a person (this session's model) assigned by looking at 240-px contact-sheet tiles: they are visual judgements, not detector output, and carry classification uncertainty (provenance such as stock vs commissioned cannot be read from a frame). Method limits are repeated in each section.", "",
     "Sampling: one frame per 15 s of the analysed span. 'S' = share of sampled frames. 'W' = segment-weighted estimate of screen time (see `aggregate.py` in the research workspace; it is an estimate, never an exact duration). Shot rhythm uses two detectors: the hard-cut detector (misses dissolves) and a dissolve-aware detector validated on one window (about +-15%).", ""]
done = 0
for vid, ch in rows:
    if vid not in agg: continue
    r = agg[vid]; d = os.path.join(HERE, "a3", vid); lab = json.load(open(os.path.join(HERE, "labels", vid + ".json")))["sheets"]
    toks = [t for n in sorted(lab, key=int) for t in lab[n]]; idx = [float(t) for t in json.load(open(os.path.join(d, "sheets", "index.json")))["times"]]
    meta = json.load(open(os.path.join(d, "meta.json"))); s2p = os.path.join(d, "shots2.json"); s2 = json.load(open(s2p)) if os.path.exists(s2p) else None
    done += 1; shutil.copy(os.path.join(HERE, "labels", vid + ".json"), os.path.join(OUT, "labels", vid + ".json"))
    L += [f"## {r['title']}", "", f"- Channel key: `{ch}`; reference channel: {meta.get('channel')}; URL: https://www.youtube.com/watch?v={vid}", f"- Views at collection: {meta.get('view_count')}; upload date: {meta.get('upload_date')}; duration {tc(meta['duration'])}; analysed {tc(r['analysed_s'])} ({r['coverage_pct']}% of the video; the cap is {meta['cap_seconds']} s)",
          f"- Sampling: {r['sampled_frames']} frames, one per 15 s; hard cuts detected {r['hard_cuts']} ({r['cuts_per_min']}/min, median gap {r['median_gap_s']} s); dissolve-aware detector {('%d boundaries = %.1f/min' % (s2['n'], s2['n'] / (s2['duration_s'] / 60))) if s2 else 'not run yet'}",
          f"- Inherited-label share (segments without a sample inside, label copied from nearest sample): {100*r['inherited_label_share']:.0f}%",
          f"- Captions (OCR, 3 x 60 s windows at 1 fps): any text in {100*r['ocr_raw_text_share']:.0f}% of OCR seconds (includes map labels, UI text); after removing frames labelled map/diagram/data/screen/document: {100*r['ocr_filtered_caption_share']:.0f}%; median words per such frame {r['caption_words_median']}; median text height {r['caption_text_height_pct_median']}% of frame height; median vertical position {r['caption_vertical_pos_median']}. Frames sampled with an overlay: {100*r['overlay_share_sampled']:.0f}%",
          f"- Audio (whole analysed span): integrated {r['audio']['integrated_lufs']} LUFS, LRA {r['audio']['lra']} LU, true peak {r['audio']['true_peak_dbtp']} dBTP, bed {r['audio']['bed_below_speech_db']} dB below speech in pauses, {r['audio']['pauses_per_min']} pauses/min (median {r['audio']['median_pause_s']} s)", "",
          "| Group | S (sampled) | W (estimate) |", "|---|---|---|"]
    for g in r["groups_sampled"]: L.append(f"| {g} | {100*r['groups_sampled'][g]:.0f}% | {100*r['groups_segment_weighted'][g]:.0f}% |")
    L += ["", "| Timecode | Duration (samples x 15 s) | Category | Caption/overlay | Frames |", "|---|---|---|---|---|"]
    i = 0
    while i < len(toks):
        j = i
        while j + 1 < len(toks) and toks[j + 1][0] == toks[i][0]: j += 1
        cap = sum("+" in t for t in toks[i:j + 1]); a, b = idx[i] - 7.5, idx[j] + 7.5
        L.append(f"| {tc(max(0, a))}-{tc(min(b, r['analysed_s']))} | {15*(j-i+1)} s | {NAMES.get(toks[i][0], toks[i][0])} | {('%d of %d frames with text overlay' % (cap, j-i+1)) if cap else 'none seen'} | {i+1}-{j+1} |")
        i = j + 1
    L += ["", "Confidence: medium for the category mix (single-frame visual labels; minority categories on fast-cut videos can be missed by 15 s sampling); medium for shot rhythm; low for provenance (real vs stock vs commissioned is not determinable from frames).", ""]
open(os.path.join(OUT, "VIDEO-RECORDS.md"), "w", encoding="utf8").write("\n".join(L))
for f in ("aggregate.json", "segments.csv"): shutil.copy(os.path.join(HERE, f), os.path.join(OUT, f))
print("records for", done, "videos")
